public static void main(String[] args) {
    String s = "wbwbwwbwbwbw";
    Scanner scanner = new Scanner(System.in);
    int w = scanner.nextInt();
    int b = scanner.nextInt();
    int totalLength = w + b;
    int cw = 0, cb = 0;

    // Extend the string to cover all possible substrings of length w + b
    String extendedString = s + s.substring(0, totalLength - 1);

    // Initialize the first window
    for (int i = 0; i < totalLength; i++) {
        if (extendedString.charAt(i) == 'w') {
            cw++;
        } else {
            cb++;
        }
    }

    boolean ans = false;
    if (cw == w && cb == b) {
        ans = true;
    }

    // Sliding window
    for (int i = 0; i < s.length(); i++) {
        if (extendedString.charAt(i) == 'w') {
            cw--;
        } else {
            cb--;
        }
        if (extendedString.charAt(i + totalLength) == 'w') {
            cw++;
        } else {
            cb++;
        }
        if (cw == w && cb == b) {
            ans = true;
            break;
        }
    }

    if (ans) {
        System.out.println("Yes");
    } else {
        System.out.println("No");
    }
}
